1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// The single customer a scenario is quoted for.
15	pub struct Customer {
16	    pub years_with_mhpco: u32,
17	}
18	
19	pub struct Item {
20	    pub item_type: String,
21	    pub material: String,
22	    pub enchantment: u32,
23	    pub cursed: bool,
24	}
25	
26	const PROCESSING_FEE: u64 = 5;
27	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
28	
29	const SWORD_BASE_PREMIUM: u64 = 100;
30	const AMULET_BASE_PREMIUM: u64 = 60;
31	const STAFF_BASE_PREMIUM: u64 = 80;
32	const POTION_BASE_PREMIUM: u64 = 40;
33	const COMPONENT_BASE_PREMIUM: u64 = 25;
34	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
35	const COMPONENT_BLOCK_SIZE: usize = 3;
36	const CURSE_SURCHARGE_PERCENT: u64 = 50;
37	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
38	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
39	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
40	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
41	const LOYALTY_YEARS: u32 = 2;
42	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
43	
44	/// Components, such as runes and moonstones, are the parts the MHPCO insures
45	/// alongside main items and the only items the building-block offer covers.
46	fn is_component(item: &Item) -> bool {
47	    matches!(item.item_type.as_str(), "rune" | "moonstone")
48	}
49	
50	/// The MHPCO price list: the base premium the catalogue lists for one item.
51	fn base_premium(item: &Item) -> u64 {
52	    if is_component(item) {
53	        return COMPONENT_BASE_PREMIUM;
54	    }
55	    match item.item_type.as_str() {
56	        "amulet" => AMULET_BASE_PREMIUM,
57	        "staff" => STAFF_BASE_PREMIUM,
58	        "potion" => POTION_BASE_PREMIUM,
59	        _ => SWORD_BASE_PREMIUM,
60	    }
61	}
62	
63	/// The building-block offer is reserved for a group of exactly 3 alike
64	/// components; a larger group does not qualify, it is priced per component.
65	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
66	    alike_component_count == COMPONENT_BLOCK_SIZE
67	}
68	
69	/// The price the MHPCO charges for one group of alike components: the
70	/// building-block offer when the group qualifies, otherwise per component.
71	fn component_group_base_premium(count: usize) -> u64 {
72	    if qualifies_as_building_block(count) {
73	        COMPONENT_BLOCK_BASE_PREMIUM
74	    } else {
75	        count as u64 * COMPONENT_BASE_PREMIUM
76	    }
77	}
78	
79	/// Two components are "alike" when they share this key. For the MHPCO,
80	/// alike means the very same catalogue type: a rune and a moonstone are
81	/// never alike, so mixed component types form no building block.
82	fn alike_group_key(item: &Item) -> &str {
83	    &item.item_type
84	}
85	
86	/// The policy base premium: the sum of all insured items' base premiums,
87	/// with alike components priced per group so a block can be recognised.
88	fn policy_base_premium(items: &[Item]) -> u64 {
89	    let mut main_items_total = 0;
90	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
91	    for item in items {
92	        if is_component(item) {
93	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
94	        } else {
95	            main_items_total += base_premium(item);
96	        }
97	    }
98	
99	    main_items_total
100	        + alike_component_counts
101	            .values()
102	            .map(|count| component_group_base_premium(*count))
103	            .sum::<u64>()
104	}
105	
106	/// In the MHPCO's favor means downwards for a payout the office owes.
107	fn payout_rounded_in_mhpco_favor(amount: f64) -> u64 {
108	    amount.floor() as u64
109	}
110	
111	/// Intermediate amounts stay fractional; only the final premium is rounded.
112	/// In the MHPCO's favor means upwards for a premium the customer owes.
113	fn premium_rounded_in_mhpco_favor(amount: f64) -> u64 {
114	    amount.ceil() as u64
115	}
116	
117	/// A policy-wide modifier is measured against the policy base premium, the
118	/// sum of all item base premiums, never against a single item.
119	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
120	    policy_base_premium * percent as f64 / 100.0
121	}
122	
123	/// Every item in a quote is treated as a first insurance, so the initial
124	/// assessment surcharge is charged on the whole policy base premium.
125	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
126	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
127	}
128	
129	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
130	/// highly enchanted. This is the premium-side threshold; the claim-side
131	/// reimbursement clause judges enchantment by its own, stricter threshold.
132	fn is_highly_enchanted(item: &Item) -> bool {
133	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
134	}
135	
136	/// An item-specific risk surcharge is charged on the base premium of the
137	/// affected item, never on the policy total.
138	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
139	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
140	}
141	
142	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
143	/// item that brings two of them is surcharged for each.
144	fn item_risk_surcharge(item: &Item) -> f64 {
145	    let mut surcharge = 0.0;
146	    if item.cursed {
147	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
148	    }
149	    if is_highly_enchanted(item) {
150	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
151	    }
152	    surcharge
153	}
154	
155	/// Item-specific modifiers apply to the base premium of the affected item,
156	/// never to the policy total, so the policy owes the sum of the items' own
157	/// risk surcharges.
158	fn item_risk_surcharges(items: &[Item]) -> f64 {
159	    items.iter().map(item_risk_surcharge).sum()
160	}
161	
162	/// A long-standing customer, with at least two years of business with the
163	/// MHPCO, has earned the loyalty discount.
164	fn is_long_standing(customer: &Customer) -> bool {
165	    customer.years_with_mhpco >= LOYALTY_YEARS
166	}
167	
168	/// The loyalty discount is a policy-wide modifier, so it is measured against
169	/// the policy base premium.
170	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
171	    if is_long_standing(customer) {
172	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
173	    } else {
174	        0.0
175	    }
176	}
177	
178	/// A contract is a follow-up when the customer already holds at least one
179	/// other contract with the MHPCO; the customer's very first is not.
180	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
181	    contracts_already_held > 0
182	}
183	
184	/// Every contract after the customer's first earns the follow-up discount. It
185	/// is a policy-wide modifier, so it is measured against the policy base premium.
186	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
187	    if is_follow_up_contract(contracts_already_held) {
188	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
189	    } else {
190	        0.0
191	    }
192	}
193	
194	/// What the customer's standing with the MHPCO adds to or takes off the policy
195	/// base premium: the net of every policy-wide surcharge and discount. Positive
196	/// amounts raise the premium, negative amounts lower it.
197	fn policy_wide_modifiers(
198	    customer: &Customer,
199	    contracts_already_held: u32,
200	    policy_base_premium: f64,
201	) -> f64 {
202	    first_insurance_surcharge(policy_base_premium)
203	        - loyalty_discount(customer, policy_base_premium)
204	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
205	}
206	
207	/// The premium the policy earns before the processing fee: the policy base
208	/// premium, plus what the items' own risks cost, plus what the customer's
209	/// standing adjusts.
210	fn modified_policy_premium(
211	    customer: &Customer,
212	    contracts_already_held: u32,
213	    items: &[Item],
214	) -> f64 {
215	    let policy_base_premium = policy_base_premium(items) as f64;
216	    policy_base_premium
217	        + item_risk_surcharges(items)
218	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
219	}
220	
221	/// The MHPCO adds its processing fee to every premium at the very end, after
222	/// every surcharge and discount has been settled.
223	pub fn quote_premium(
224	    customer: &Customer,
225	    contracts_already_held: u32,
226	    items: &[Item],
227	) -> u64 {
228	    premium_rounded_in_mhpco_favor(
229	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
230	    )
231	}
232	
233	/// A deductible applies per damage event, that is once per damaged item.
234	fn reimbursement_for(damage: &Damage) -> f64 {
235	    (damage.amount as f64 - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
236	}
237	
238	pub fn claim_payout(_items: &[Item], incident: &Incident) -> u64 {
239	    payout_rounded_in_mhpco_favor(incident.damages.iter().map(reimbursement_for).sum())
240	}
