/// A deductible applies per damage event, that is once per damaged item.
fn reimbursement_for(damage: &Damage) -> f64 {
    (damage.amount as f64 - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
}

pub fn claim_payout(_items: &[Item], incident: &Incident) -> u64 {
    rounded_in_mhpco_favor(
        incident.damages.iter().map(reimbursement_for).sum(),
        Debtor::Mhpco,
    )
}

